alter table public.content_publication_claims add column if not exists error_message text;alter table public.content_publication_claims drop constraint if exists content_publication_claims_status_check;alter table public.content_publication_claims add constraint content_publication_claims_status_check check(status in('processing','completed','failed'));
create or replace function public.fail_reading_completion(p_session_id uuid,p_error text)returns void language plpgsql security definer set search_path=public as $$begin if current_setting('request.jwt.claim.role',true) is distinct from 'service_role' then raise exception 'service role required' using errcode='42501';end if;update public.reading_completion_runs set status='failed',error_message=left(p_error,1000),completed_at=now()where session_id=p_session_id and status='processing';update public.reading_sessions set abandoned=true where id=p_session_id and completed_at is null;end;$$;
create or replace function public.fail_content_publication(p_candidate_id uuid,p_error text)returns void language plpgsql security definer set search_path=public as $$begin if current_setting('request.jwt.claim.role',true) is distinct from 'service_role' then raise exception 'service role required' using errcode='42501';end if;update public.content_publication_claims set status='failed',error_message=left(p_error,1000),completed_at=now()where candidate_id=p_candidate_id and status='processing';end;$$;
create or replace function public.claim_content_publication(p_candidate_id uuid) returns table(claimed boolean,status text,result_payload jsonb) language plpgsql security definer set search_path=public as $$declare v public.content_publication_claims%rowtype;begin if current_setting('request.jwt.claim.role',true) is distinct from 'service_role' then raise exception 'service role required' using errcode='42501';end if;insert into public.content_publication_claims(candidate_id)values(p_candidate_id)on conflict do nothing returning * into v;if found then return query select true,v.status,v.result_payload;return;end if;select * into v from public.content_publication_claims where candidate_id=p_candidate_id for update;if v.status='failed' then update public.content_publication_claims set status='processing',error_message=null,started_at=now(),completed_at=null,result_payload=null where candidate_id=p_candidate_id returning * into v;return query select true,v.status,v.result_payload;return;end if;return query select false,v.status,v.result_payload;end;$$;
revoke all on function public.fail_reading_completion(uuid,text),public.fail_content_publication(uuid,text) from public,anon,authenticated;grant execute on function public.fail_reading_completion(uuid,text),public.fail_content_publication(uuid,text) to service_role;
